const { createApp } = require("./app");
const { sequelize } = require("./models");
const { seed } = require("./seed");

const PORT = process.env.PORT || 3001;

async function start() {
  try {
    await sequelize.sync({ alter: true });
    await seed();

    const app = createApp();
    app.listen(PORT, () =>
      console.log(`Server running on http://localhost:${PORT}`),
    );
  } catch (error) {
    console.error("Unable to start:", error);
    process.exit(1);
  }
}

start();

"use strict";

const { Sequelize, DataTypes, Model } = require("sequelize");

const USER_HIDDEN_ATTRIBUTES = ["id", "updatedAt", "createdAt"];
const ARTICLE_HIDDEN_ATTRIBUTES = ["id", "userId"];
const COMMENT_HIDDEN_ATTRIBUTES = ["articleId", "userId"];

const sequelize = new Sequelize({
  dialect: "sqlite",
  storage: ":memory:",
  logging: false,
});

function toPublicJSON(instance, hiddenAttributes) {
  const data = { ...instance.get() };
  hiddenAttributes.forEach((attribute) => {
    delete data[attribute];
  });
  return data;
}

class User extends Model {
  static associate() {
    this.hasMany(Article, { foreignKey: "userId", onDelete: "CASCADE" });
    this.hasMany(Comment, { foreignKey: "userId" });
  }

  toJSON() {
    return toPublicJSON(this, USER_HIDDEN_ATTRIBUTES);
  }
}

class Article extends Model {
  static associate() {
    this.belongsTo(User, { foreignKey: "userId", as: "author" });
    this.hasMany(Comment, { foreignKey: "articleId", onDelete: "cascade" });
  }

  toJSON() {
    return toPublicJSON(this, ARTICLE_HIDDEN_ATTRIBUTES);
  }
}

class Comment extends Model {
  static associate() {
    this.belongsTo(Article, { foreignKey: "articleId" });
    this.belongsTo(User, { as: "author", foreignKey: "userId" });
  }

  toJSON() {
    return toPublicJSON(this, COMMENT_HIDDEN_ATTRIBUTES);
  }
}

User.init(
  { username: DataTypes.STRING },
  { sequelize, modelName: "User" },
);

Article.init(
  { slug: DataTypes.STRING },
  { sequelize, modelName: "Article" },
);

Comment.init(
  {
    id: {
      allowNull: false,
      autoIncrement: true,
      primaryKey: true,
      type: DataTypes.INTEGER,
    },
    body: DataTypes.TEXT,
  },
  { sequelize, modelName: "Comment" },
);

User.associate();
Article.associate();

